#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    long long countStableSubarrays(vector<int>& nums) {
        int n = nums.size();
        vector<long long> P(n + 1, 0);
        for (int i = 0; i < n; ++i) P[i + 1] = P[i] + nums[i];
        long long count = 0;
        unordered_map<long long, int> left_counts;
        for (int j = 2; j < n; ++j) {
            int i = j - 2;
            long long left_key = nums[i] + P[i + 1];
            left_counts[left_key]++;
            long long right_key = P[j] - nums[j];
            if (left_counts.count(right_key)) {
                count += left_counts[right_key];
            }
        }
        return count;
    }
};

import java.util.*;

class Solution {
    public long countStableSubarrays(int[] nums) {
        int n = nums.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        long count = 0;
        Map<Long, Integer> leftCounts = new HashMap<>();
        for (int j = 2; j < n; j++) {
            int i = j - 2;
            long leftKey = nums[i] + P[i + 1];
            leftCounts.put(leftKey, leftCounts.getOrDefault(leftKey, 0) + 1);
            long rightKey = P[j] - nums[j];
            count += leftCounts.getOrDefault(rightKey, 0);
        }
        return count;
    }
}

